package com.anpahn.staffguard.security;
import java.time.Duration; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicInteger;
public final class RateLimiter<K>{private final int max;private final long window;private final ConcurrentHashMap<K,Window> map=new ConcurrentHashMap<>();public RateLimiter(int max,Duration window){if(max<1||window.isNegative()||window.isZero())throw new IllegalArgumentException();this.max=max;this.window=window.toMillis();}public boolean tryAcquire(K key){long now=System.currentTimeMillis();Window w=map.compute(key,(k,o)->o==null||now-o.start>=window?new Window(now):o);return w.count.incrementAndGet()<=max;}public void cleanup(){long n=System.currentTimeMillis();map.entrySet().removeIf(e->n-e.getValue().start>=window);}private static final class Window{final long start;final AtomicInteger count=new AtomicInteger();Window(long s){start=s;}}}
